using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.HighDefinition;
public static class HangarLampsAndProps {
const string A="Assets/NewMap/HangarLamps/";static Transform props;static Material atlas;static int propCount;
static GameObject Spawn(string name,Vector3 p,Vector3 rotation,float scale=1){string path=AssetDatabase.FindAssets(name+" t:Prefab").Select(AssetDatabase.GUIDToAssetPath).First(x=>Path.GetFileNameWithoutExtension(x)==name);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),props);g.transform.position=p;g.transform.rotation=Quaternion.Euler(rotation);g.transform.localScale=Vector3.one*scale;foreach(var r in g.GetComponentsInChildren<Renderer>(true)){var ms=r.sharedMaterials;for(int i=0;i<ms.Length;i++)if(ms[i]&&ms[i].name=="TFP_Atlas_1A")ms[i]=atlas;r.sharedMaterials=ms;}var bounds=new Bounds();bool first=true;foreach(var r in g.GetComponentsInChildren<Renderer>()){if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}g.transform.position+=Vector3.up*(p.y-bounds.min.y);propCount++;return g;}
static GameObject Box(string n,Transform parent,Vector3 p,Vector3 s,Material mat,bool collider=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
static Material Mat(string n,Color c,float smooth){var m=new Material(Shader.Find("HDRP/Lit")){name=n};m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",smooth);HDMaterial.ValidateMaterial(m);AssetDatabase.CreateAsset(m,A+n+".mat");return m;}
static Mesh Shade(){var v=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();float[] radii={.115f,.13f,.22f,.36f,.50f,.51f};float[] ys={.66f,.48f,.29f,.11f,.025f,0};int n=48;for(int j=0;j<radii.Length;j++)for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;v.Add(new Vector3(Mathf.Cos(a)*radii[j],ys[j],Mathf.Sin(a)*radii[j]));uv.Add(new Vector2(i/(float)n,j/(float)(radii.Length-1)));}for(int j=0;j<radii.Length-1;j++)for(int i=0;i<n;i++){int b=j*(n+1)+i,c=b+n+1;tris.AddRange(new[]{b,b+1,c,b+1,c+1,c});}var mesh=new Mesh{name="Spun bell pendant shade"};mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"Bell shade.asset");return mesh;}
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var root=GameObject.Find("New_Map").transform;var h=root.Find("01_Modular_Hangar");if(h.Find("Reference pendant lamps"))throw new Exception("Already authored");Directory.CreateDirectory(A);Directory.CreateDirectory("output/NewMap/LampsAndProps");AssetDatabase.Refresh();atlas=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/Materials/TFP_Atlas_1A - NewMap quality.mat");
var lamps=new GameObject("Reference pendant lamps").transform;lamps.SetParent(h,false);props=new GameObject("Wall side farm storage and ladders").transform;props.SetParent(root.Find("02_Hangar_Props"),false);
AssetDatabase.StartAssetEditing();try{
var metal=Mat("Aged charcoal pendant enamel",new Color(.12f,.105f,.085f),.43f);metal.SetFloat("_DoubleSidedEnable",1);HDMaterial.ValidateMaterial(metal);var cable=Mat("Dark lamp flex",new Color(.025f,.021f,.018f),.2f);var glow=Mat("Warm textured diffuser emission",new Color(.95f,.8f,.55f),.28f);
var tex=new Texture2D(256,256,TextureFormat.RGBA32,true,true){name="Warm lamp emission mask",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Trilinear};var px=new Color[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++){float d=Vector2.Distance(new Vector2(x,y),new Vector2(127.5f,127.5f))/128;float value=Mathf.Lerp(1,.65f,Mathf.Clamp01(d))*(.98f+.02f*Mathf.PerlinNoise(x*.11f,y*.11f));px[y*256+x]=new Color(value,value*.92f,value*.75f,1);}tex.SetPixels(px);tex.Apply(true);AssetDatabase.CreateAsset(tex,A+"WarmLamp_Emission.asset");glow.SetTexture("_EmissiveColorMap",tex);glow.SetColor("_EmissiveColor",new Color(10,7.5f,4.2f));glow.SetFloat("_UseEmissiveIntensity",0);HDMaterial.ValidateMaterial(glow);EditorUtility.SetDirty(glow);var shade=Shade();
var sources=h.Cast<Transform>().Where(t=>t.name=="Warm pendant").ToArray();int index=0;foreach(var lightSource in sources){float z=lightSource.position.z;var lamp=new GameObject("Bell pendant "+(++index)).transform;lamp.SetParent(lamps,false);lamp.localPosition=new Vector3(-1,8.1f,z);var shell=new GameObject("Spun metal bell shade");shell.transform.SetParent(lamp,false);shell.AddComponent<MeshFilter>().sharedMesh=shade;shell.AddComponent<MeshRenderer>().sharedMaterial=metal;
var disc=GameObject.CreatePrimitive(PrimitiveType.Sphere);disc.name="Warm luminous glass underside";disc.transform.SetParent(lamp,false);disc.transform.localPosition=new Vector3(0,.035f,0);disc.transform.localScale=new Vector3(.94f,.12f,.94f);disc.GetComponent<Renderer>().sharedMaterial=glow;disc.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.Off;UnityEngine.Object.DestroyImmediate(disc.GetComponent<Collider>());
Box("Suspension cable",lamp,new Vector3(0,4.2f,0),new Vector3(.027f,7.1f,.027f),cable,false);var cap=GameObject.CreatePrimitive(PrimitiveType.Cylinder);cap.name="Socket cap";cap.transform.SetParent(lamp,false);cap.transform.localPosition=new Vector3(0,.7f,0);cap.transform.localScale=new Vector3(.19f,.08f,.19f);cap.GetComponent<Renderer>().sharedMaterial=metal;UnityEngine.Object.DestroyImmediate(cap.GetComponent<Collider>());
lightSource.position=lamp.position+Vector3.down*.14f;lightSource.SetParent(lamp,true);
}foreach(Transform t in h)if(t.name=="Pendant shade"||t.name=="Pendant cable")t.gameObject.SetActive(false);
Spawn("TFP_Ladder_01A",new Vector3(-7.5f,.04f,14.0f),new Vector3(-9,90,0),1.4f);Spawn("TFP_Ladder_02A",new Vector3(-9.1f,.04f,5.2f),new Vector3(0,0,8),1);
for(int i=0;i<3;i++)Spawn("TFP_Wooden_Pallet_01A",new Vector3(-8.35f,.04f+i*.29f,11.4f),new Vector3(0,5+i*3,0),1.45f);
Spawn("TFP_Cereal_Sack_01A",new Vector3(-8.35f,.95f,11.4f),new Vector3(0,15,0),1.1f);Spawn("TFP_Bucket_Metal_01A",new Vector3(-6.8f,.04f,12.9f),Vector3.zero,1.15f);Spawn("TFP_Broom_01A",new Vector3(-9.0f,.04f,12.5f),new Vector3(0,90,-8),1.1f);
Spawn("TFP_Tool_Storage_01A",new Vector3(-8.8f,.04f,-12.8f),Vector3.zero);Spawn("TFP_Tool_Rack_01A",new Vector3(-9.3f,.04f,-10.3f),Vector3.zero);Spawn("TFP_Metal_Barrel_01A",new Vector3(-5.6f,.04f,-13.6f),Vector3.zero);Spawn("TFP_Bucket_Wood_01A",new Vector3(-6.6f,.04f,-13.1f),Vector3.zero);
Spawn("TFP_House_Stairs_01A",new Vector3(7.8f,.04f,-9.4f),new Vector3(0,180,0),.6f);
var wood=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/TallHangar/Rich oak framing.mat");Box("Rear storage landing",props,new Vector3(7.8f,1.73f,-10.3f),new Vector3(1.8f,.22f,1.8f),wood);foreach(float x in new[]{7f,8.6f})foreach(float z in new[]{-11.1f,-9.5f})Box("Landing support post",props,new Vector3(x,.86f,z),new Vector3(.16f,1.72f,.16f),wood);Spawn("TFP_Wooden_Crate_01A",new Vector3(7.9f,1.85f,-10.6f),Vector3.zero,.8f);
}finally{AssetDatabase.StopAssetEditing();}
AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());string report="Three shaped bell pendant lamps with warm emission texture and existing real lights; "+propCount+" original farm prefab instances including tall entrance ladder, second ladder, pallets, sacks, tools, buckets, barrel and rear storage steps/landing. Source assets unchanged.";File.WriteAllText("output/NewMap/LampsAndProps/summary.txt",report);return report;}
}
